                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Credit Card</span>
                                <span className="text-[9px] font-bold text-slate-400">Total Debt</span>
                            </div>
                            <CreditCard className="w-4 h-4 text-rose-400" />
