                                <button onClick={() => { onAskCoach && onAskCoach("Generate a monthly financial report."); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <FileText className="w-3 h-3 text-emerald-400" /> Generate Monthly Report
