        ...(userBackground ? { backgroundImage: `url(${userBackground})`, backgroundSize: 'cover', backgroundPosition: 'center', backgroundAttachment: 'fixed' } : {})
    }}
  >
    {/* Atmosphere Overlay - Adjusted opacity to 40% to allow background to shine through */}
    {userBackground && (
        <div className="absolute inset-0 bg-slate-950/40 z-0 pointer-events-none backdrop-blur-[1px]"></div>
    )}

