                            <div className={`relative w-6 h-6 rounded-full overflow-hidden border border-white/10 transition-all hover:scale-110 ${!['#020617', '#000000', '#1e1b4b', '#022c22', '#2e1065', '#450a0a'].includes(userThemeColor) ? 'ring-2 ring-white scale-110 shadow-lg shadow-white/20' : ''}`} style={{ backgroundColor: userThemeColor }}>
                                <input 
                                    type="color" 
                                    value={userThemeColor}
                                    onChange={(e) => onUpdateThemeColor(e.target.value)}
                                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 p-0 border-0 cursor-pointer opacity-0"
                                    title="Custom Color"
                                />
                                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
