import React, { useMemo } from 'react';
import { Transaction, TransactionType, UserPlan } from '../types';
import { ResponsiveContainer, Sankey, Tooltip, Layer, Rectangle } from 'recharts';
import { Waves, ArrowRightLeft, TrendingUp, AlertCircle } from 'lucide-react';

interface MoneyFlowProps {
  transactions: Transaction[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const MoneyFlow: React.FC<MoneyFlowProps> = ({ transactions, formatCurrency, userPlan }) => {
  const isElite = userPlan === 'ultra';

  const data = useMemo(() => {
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();

    const monthTxs = transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const income = monthTxs
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((acc, t) => acc + t.amount, 0);

    const expenseMap: Record<string, number> = {};
    monthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        expenseMap[t.category] = (expenseMap[t.category] || 0) + t.amount;
    });

    const totalExpenses = Object.values(expenseMap).reduce((a, b) => a + b, 0);
    const savings = Math.max(0, income - totalExpenses);
    const deficit = Math.max(0, totalExpenses - income);

    // Nodes Construction
    const nodes = [
        { name: 'Total Inflow', color: '#10b981' }, // 0
        ...(deficit > 0 ? [{ name: 'Reserves/Credit', color: '#f43f5e' }] : []), // Conditional Node
    ];

    const categoryNodes = Object.keys(expenseMap).map(cat => ({ name: cat, color: '#6366f1' }));
    const savingsNode = savings > 0 ? [{ name: 'Retained', color: '#10b981' }] : [];

    // Adjust indices based on deficit node presence
    const startIndex = deficit > 0 ? 2 : 1; 

    // Add sinks to nodes list
    nodes.push(...categoryNodes, ...savingsNode);

    // Links Construction
    const links = [];

    // Link Index Mapping
    // 0: Income
    // 1: Reserves (if deficit) OR First Category

    let currentSinkIndex = startIndex;

    // Expenses Mapping
    Object.entries(expenseMap).forEach(([cat, amount]) => {
        // If we have a deficit, we need to split the source flow
        // Ideally, Income fills first, then Reserves.
        // Simplified Logic for Viz: Income flows to all proportional to their size, Reserves fill the rest.

        if (deficit === 0) {
            // Simple Case: Income covers everything
            links.push({ source: 0, target: currentSinkIndex, value: amount });
        } else {
            // Deficit Case: Flow mixing
            // This is complex for a simple Sankey. 
            // Simplified: All categories pull from "Income" up to Income amount, then "Reserves".
            // Actually, visuals are better if we just show Total Liquidity (Income + Deficit) -> Categories
            // But let's try to be distinct.

            // For MVP stability: Just link Income -> Category. 
            // If Income < Expenses, the Sankey logic might fail if we don't supply enough source value.
            // So we added "Reserves/Credit" node (Index 1) if deficit exists.

            // Distribute 'Reserves' flow proportionally or just dump it into the largest expense?
            // Let's distribute based on ratio.
            const ratio = amount / totalExpenses;
            const portionFromIncome = income * ratio;
            const portionFromReserves = deficit * ratio;

            if (portionFromIncome > 0) links.push({ source: 0, target: currentSinkIndex, value: portionFromIncome });
            if (portionFromReserves > 0) links.push({ source: 1, target: currentSinkIndex, value: portionFromReserves });
        }
        currentSinkIndex++;
    });

    // Savings Mapping
    if (savings > 0) {
        links.push({ source: 0, target: currentSinkIndex, value: savings });
    }

    return { nodes, links, income, totalExpenses, savings, deficit };
  }, [transactions]);

  if (data.income === 0 && data.totalExpenses === 0) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[400px] text-center p-10 bg-slate-900/20 rounded-[3rem] border border-white/5">
            <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center mb-6">
                <Waves className="w-10 h-10 text-slate-500" />
            </div>
            <h3 className="text-2xl font-bold text-white mb-2">Flow Inactive</h3>
            <p className="text-slate-400 max-w-md">Log income and expenses to visualize the kinetic movement of your capital.</p>
        </div>
      );
  }

  // Custom Tooltip for Sankey
  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const isLink = data.source && data.target;

      return (
        <div className="bg-slate-950/90 border border-white/10 p-3 rounded-xl shadow-xl backdrop-blur-md">
          {isLink ? (
             <div className="text-xs">
                 <span className="text-slate-400">{data.source.name}</span>
                 <ArrowRightLeft className="w-3 h-3 inline mx-2 text-indigo-400" />
                 <span className="text-slate-400">{data.target.name}</span>
                 <div className="text-white font-bold mt-1 text-sm">{formatCurrency(data.value)}</div>
             </div>
          ) : (
             <div className="text-xs">
                 <div className="text-slate-400 font-bold mb-1">{data.name}</div>
                 <div className="text-white font-bold text-sm">{formatCurrency(data.value)}</div>
             </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="animate-slide-up pb-20 space-y-8">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3 uppercase">
               <Waves className="w-8 h-8 text-cyan-400" />
               Kinetic Money Flow
            </h2>
            <span className="px-3 py-1 rounded-full bg-cyan-500/20 text-cyan-400 text-[10px] font-black tracking-widest border border-cyan-500/30">SANKEY VISUALIZER</span>
          </div>
          <p className="text-slate-400 font-medium">Trace every dollar from source to destination.</p>
        </div>
      </div>

      <div className="glass-card p-6 md:p-10 rounded-[3rem] border border-white/10 bg-[#020617] relative overflow-hidden min-h-[600px] flex flex-col">
          {/* Legend / Header Stats */}
          <div className="flex flex-wrap gap-6 mb-8 relative z-10">
              <div className="flex items-center gap-3 px-4 py-2 bg-emerald-900/20 border border-emerald-500/20 rounded-xl">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_10px_#10b981]"></div>
                  <div>
                      <div className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Source Inflow</div>
                      <div className="text-sm font-bold text-white">{formatCurrency(data.income)}</div>
                  </div>
              </div>
              <div className="flex items-center gap-3 px-4 py-2 bg-rose-900/20 border border-rose-500/20 rounded-xl">
                  <div className="w-2 h-2 rounded-full bg-rose-500 shadow-[0_0_10px_#f43f5e]"></div>
                  <div>
                      <div className="text-[9px] font-black text-rose-500 uppercase tracking-widest">Total Outflow</div>
                      <div className="text-sm font-bold text-white">{formatCurrency(data.totalExpenses)}</div>
                  </div>
              </div>
              {data.deficit > 0 && (
                  <div className="flex items-center gap-2 px-3 py-2 bg-amber-500/10 border border-amber-500/20 rounded-xl animate-pulse">
                      <AlertCircle className="w-4 h-4 text-amber-500" />
                      <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Deficit Detected</span>
                  </div>
              )}
          </div>

          <div className="flex-1 w-full relative z-10 min-h-[500px]">
              <ResponsiveContainer width="100%" height="100%">
                  <Sankey
                    data={data}
                    nodeWidth={15}
                    nodePadding={20}
                    linkCurvature={0.4}
                    margin={{ left: 20, right: 20, top: 20, bottom: 20 }}
                  >
                    <Tooltip content={<CustomTooltip />} />
                    <Layer key="nodes">
                        {(props: any) => {
                            const { nodes } = props;
                            return nodes.map((node: any, i: number) => {
                                // Custom Node Rendering
                                const isIncome = i === 0 || node.name === 'Reserves/Credit';
                                const isSavings = node.name === 'Retained';
                                return (
                                    <g key={`node-${i}`}>
                                        <Rectangle
                                            x={node.x}
                                            y={node.y}
                                            width={node.width}
                                            height={node.height}
                                            fill={node.color || (isSavings ? '#10b981' : isIncome ? '#10b981' : '#6366f1')}
                                            fillOpacity={0.8}
                                            radius={4}
                                        />
                                        <text
                                            x={node.x + (isIncome ? -10 : node.width + 10)}
                                            y={node.y + node.height / 2}
                                            textAnchor={isIncome ? 'end' : 'start'}
                                            alignmentBaseline="middle"
                                            fill="#fff"
                                            fontSize={10}
                                            fontWeight="bold"
                                            className="uppercase tracking-wider"
                                        >
                                            {node.name}
                                        </text>
                                        <text
                                            x={node.x + (isIncome ? -10 : node.width + 10)}
                                            y={node.y + node.height / 2 + 12}
                                            textAnchor={isIncome ? 'end' : 'start'}
                                            alignmentBaseline="middle"
                                            fill="#94a3b8"
                                            fontSize={9}
                                            fontWeight="normal"
                                        >
                                            {formatCurrency(node.value)}
                                        </text>
                                    </g>
                                );
                            });
                        }}
                    </Layer>
                    <Layer key="links">
                        {(props: any) => {
                            const { links } = props;
                            return links.map((link: any, i: number) => {
                                const isRetained = link.target.name === 'Retained';
                                return (
                                    <path
                                        key={`link-${i}`}
                                        d={link.d} // Recharts calculates path 'd' attribute
                                        stroke={isRetained ? "url(#gradSavings)" : "url(#gradExpense)"}
                                        strokeWidth={Math.max(1, link.strokeWidth)}
                                        fill="none"
                                        strokeOpacity={0.3}
                                        className="transition-all hover:stroke-opacity-60"
                                    />
                                );
                            });
                        }}
                    </Layer>
                  </Sankey>
              </ResponsiveContainer>

              {/* Gradients for links */}
              <svg width="0" height="0">
                  <defs>
                      <linearGradient id="gradExpense" x1="0" y1="0" x2="1" y2="0">
                          <stop offset="0%" stopColor="#10b981" />
                          <stop offset="100%" stopColor="#f43f5e" />
                      </linearGradient>
                      <linearGradient id="gradSavings" x1="0" y1="0" x2="1" y2="0">
                          <stop offset="0%" stopColor="#10b981" />
                          <stop offset="100%" stopColor="#10b981" />
                      </linearGradient>
                  </defs>
              </svg>
          </div>
      </div>
    </div>
  );
};

