import React, { useMemo } from 'react';
import { Transaction, TransactionType, UserPlan } from '../types';
import { ResponsiveContainer, Sankey, Tooltip, Rectangle } from 'recharts';
import { Waves, ArrowRightLeft, AlertCircle } from 'lucide-react';

interface MoneyFlowProps {
  transactions: Transaction[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

// Rich palette for categories
const CATEGORY_COLORS = [
  '#6366f1', // Indigo
  '#ec4899', // Pink
  '#8b5cf6', // Violet
  '#06b6d4', // Cyan
  '#f59e0b', // Amber
  '#3b82f6', // Blue
  '#14b8a6', // Teal
  '#f43f5e', // Rose
  '#84cc16', // Lime
  '#a855f7', // Purple
];

const MoneyFlow: React.FC<MoneyFlowProps> = ({ transactions, formatCurrency, userPlan }) => {
  const data = useMemo(() => {
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();

    const monthTxs = transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const income = monthTxs
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((acc, t) => acc + t.amount, 0);

    const expenseMap: Record<string, number> = {};
    monthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        expenseMap[t.category] = (expenseMap[t.category] || 0) + t.amount;
    });

    const totalExpenses = Object.values(expenseMap).reduce((a, b) => a + b, 0);
    const savings = Math.max(0, income - totalExpenses);
    const deficit = Math.max(0, totalExpenses - income);

    // Nodes Construction
    // Source Nodes
    const nodes: {name: string, color: string}[] = [
        { name: 'Total Inflow', color: '#10b981' }, // Index 0
    ];

    if (deficit > 0) {
        nodes.push({ name: 'Reserves/Credit', color: '#ef4444' });
    }

    // Sinks (Expenses + Savings)
    // Sort expenses by amount desc
    const sortedCategories = Object.entries(expenseMap).sort((a, b) => b[1] - a[1]);

    const categoryNodes = sortedCategories.map(([cat, val], idx) => ({ 
        name: cat, 
        color: CATEGORY_COLORS[idx % CATEGORY_COLORS.length] 
    }));

    // Add Savings Node if there is savings
    if (savings > 0) {
        categoryNodes.push({ name: 'Retained', color: '#059669' });
    }

    // Combine
    nodes.push(...categoryNodes);

    // Indices
    const sourceIncomeIndex = 0;
    const sourceDeficitIndex = deficit > 0 ? 1 : -1;
    const firstSinkIndex = deficit > 0 ? 2 : 1;

    // Links Construction
    const links: any[] = [];

    let currentSinkIndex = firstSinkIndex;

    // Map Expense Links
    sortedCategories.forEach(([cat, amount]) => {
        // If we have a deficit, expenses are paid proportionally by Income and Reserves (simplified model)
        // Or simplified: Income pays as much as it can, Reserves pay the rest? 
        // Proportional is usually visually better.

        const totalSource = income + deficit; // Should equal totalExpenses + savings (if deficit=0)

        if (deficit === 0) {
            // All from Income
            links.push({ source: sourceIncomeIndex, target: currentSinkIndex, value: amount });
        } else {
            // Mixed source
            const incomeRatio = income / totalSource;
            const deficitRatio = deficit / totalSource;

            if (income > 0) {
                links.push({ source: sourceIncomeIndex, target: currentSinkIndex, value: amount * incomeRatio });
            }
            links.push({ source: sourceDeficitIndex, target: currentSinkIndex, value: amount * deficitRatio });
        }
        currentSinkIndex++;
    });

    // Map Savings Link (Only from Income, impossible if deficit > 0)
    if (savings > 0) {
        // The last node added was Retained
        // currentSinkIndex is pointing to it? No, loop incremented it one past the last category.
        // Wait, I added Retained to categoryNodes array.
        // So the index is correct.
        links.push({ source: sourceIncomeIndex, target: currentSinkIndex, value: savings });
    }

    return { nodes, links, income, totalExpenses, savings, deficit };
  }, [transactions]);

  if (data.income === 0 && data.totalExpenses === 0) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[400px] text-center p-10 bg-slate-900/20 rounded-[3rem] border border-white/5">
            <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center mb-6">
                <Waves className="w-10 h-10 text-slate-500" />
            </div>
            <h3 className="text-2xl font-bold text-white mb-2">Flow Inactive</h3>
            <p className="text-slate-400 max-w-md">Log income and expenses to visualize the kinetic movement of your capital.</p>
        </div>
      );
  }

  // Custom Tooltip for Sankey
  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const d = payload[0].payload;
      const isLink = d.source && d.target;

      return (
        <div className="bg-slate-950/90 border border-white/10 p-3 rounded-xl shadow-xl backdrop-blur-md min-w-[200px] relative z-50">
          {isLink ? (
             <div className="text-xs">
                 <div className="flex justify-between items-center mb-2">
                    <span className="text-slate-400 font-medium">{d.source.name}</span>
                    <ArrowRightLeft className="w-3 h-3 text-slate-600" />
                    <span className="text-white font-bold">{d.target.name}</span>
                 </div>
                 <div className="p-2 bg-white/5 rounded-lg border border-white/5 flex justify-between items-center">
                    <span className="text-slate-400">Flow</span>
                    <span className="text-emerald-400 font-mono font-bold">{formatCurrency(d.value)}</span>
                 </div>
             </div>
          ) : (
             <div className="text-xs">
                 <div className="text-slate-400 font-bold mb-1 uppercase tracking-wider">{d.name}</div>
                 <div className="text-2xl font-black text-white">{formatCurrency(d.value)}</div>
             </div>
          )}
        </div>
      );
    }
    return null;
  };

  const CustomLink = (props: any) => {
      const { sourceX, targetX, sourceY, targetY, sourceControlX, targetControlX, linkWidth, index, source, target } = props;

      const d = `
        M${sourceX},${sourceY}
        C${sourceControlX},${sourceY} ${targetControlX},${targetY} ${targetX},${targetY}
        L${targetX},${targetY + linkWidth}
        C${targetControlX},${targetY + linkWidth} ${sourceControlX},${sourceY + linkWidth} ${sourceX},${sourceY + linkWidth}
        Z
      `;

      const gradientId = `linkGrad-${index}`;
      const sourceColor = source?.color || '#94a3b8';
      const targetColor = target?.color || '#94a3b8';

      return (
        <g>
            <defs>
                <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0%" stopColor={sourceColor} stopOpacity={0.4} />
                    <stop offset="100%" stopColor={targetColor} stopOpacity={0.4} />
                </linearGradient>
            </defs>
            <path 
                d={d} 
                fill={`url(#${gradientId})`}
                stroke="none"
                className="transition-all duration-300 hover:opacity-80 cursor-pointer" 
                style={{ mixBlendMode: 'plus-lighter' }}
            />
        </g>
      );
  };

  const CustomNode = ({ x, y, width, height, index, payload, containerWidth }: any) => {
      const isSource = payload.name === 'Total Inflow' || payload.name === 'Reserves/Credit';
      const isRightSide = x > (containerWidth || 500) / 2;

      return (
        <g>
            <Rectangle
                x={x}
                y={y}
                width={width}
                height={height}
                fill={payload.color}
                fillOpacity={0.9}
                radius={4}
                stroke="rgba(255,255,255,0.1)"
                strokeWidth={1}
            />
            {/* Label */}
            <text
                x={isSource ? x - 10 : x + width + 10}
                y={y + height / 2 - 6}
                textAnchor={isSource ? 'end' : 'start'}
                alignmentBaseline="middle"
                fill="#fff"
                fontSize={11}
                fontWeight="bold"
                className="uppercase tracking-tight"
            >
                {payload.name}
            </text>
            <text
                x={isSource ? x - 10 : x + width + 10}
                y={y + height / 2 + 8}
                textAnchor={isSource ? 'end' : 'start'}
                alignmentBaseline="middle"
                fill={payload.color} 
                fontSize={10}
                fontWeight="bold"
                fontFamily="monospace"
            >
                {formatCurrency(payload.value)}
            </text>
        </g>
      );
  };

  return (
    <div className="animate-slide-up pb-20 space-y-8">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3 uppercase">
               <Waves className="w-8 h-8 text-cyan-400" />
               Kinetic Money Flow
            </h2>
            <span className="px-3 py-1 rounded-full bg-cyan-500/20 text-cyan-400 text-[10px] font-black tracking-widest border border-cyan-500/30">SANKEY VISUALIZER</span>
          </div>
          <p className="text-slate-400 font-medium">Trace every dollar from source to destination.</p>
        </div>
      </div>

      <div className="glass-card p-6 md:p-10 rounded-[3rem] border border-white/10 bg-[#020617] relative overflow-hidden min-h-[600px] flex flex-col">
          {/* Legend / Header Stats */}
          <div className="flex flex-wrap gap-6 mb-8 relative z-10">
              <div className="flex items-center gap-3 px-4 py-2 bg-emerald-900/20 border border-emerald-500/20 rounded-xl">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_10px_#10b981]"></div>
                  <div>
                      <div className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Source Inflow</div>
                      <div className="text-sm font-bold text-white">{formatCurrency(data.income)}</div>
                  </div>
              </div>
              <div className="flex items-center gap-3 px-4 py-2 bg-rose-900/20 border border-rose-500/20 rounded-xl">
                  <div className="w-2 h-2 rounded-full bg-rose-500 shadow-[0_0_10px_#f43f5e]"></div>
                  <div>
                      <div className="text-[9px] font-black text-rose-500 uppercase tracking-widest">Total Outflow</div>
                      <div className="text-sm font-bold text-white">{formatCurrency(data.totalExpenses)}</div>
                  </div>
              </div>
              {data.deficit > 0 && (
                  <div className="flex items-center gap-2 px-3 py-2 bg-amber-500/10 border border-amber-500/20 rounded-xl animate-pulse">
                      <AlertCircle className="w-4 h-4 text-amber-500" />
                      <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Deficit Detected</span>
                  </div>
              )}
