import React, { useMemo, useState } from 'react';
import { Transaction, TransactionType, UserPlan, Category } from '../types';
import { ResponsiveContainer, Sankey, Tooltip, Rectangle } from 'recharts';
import { Wallet, Info } from 'lucide-react';

interface MoneyFlowProps {
  transactions: Transaction[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

// Color Palette mimicking the reference image (SankeyMatic style)
const THEME = {
  income: '#facc15',      // Yellow-400 (Sources)
  budget: '#a3e635',      // Lime-400 (Central Node)
  savings: '#10b981',     // Emerald-500
  housing: '#818cf8',     // Indigo-400
  shopping: '#e879f9',    // Fuchsia-400
  food: '#60a5fa',        // Blue-400
  transport: '#f87171',   // Red-400
  utilities: '#2dd4bf',   // Teal-400
  insurance: '#fb923c',   // Orange-400
  other: '#94a3b8',       // Slate-400
  debt: '#ef4444'         // Red-500
};

const getCategoryColor = (cat: string): string => {
  if (cat === 'Savings') return THEME.savings;
  if (cat === 'Unallocated') return THEME.savings;
  switch (cat) {
    case Category.HOUSING: return THEME.housing;
    case Category.SHOPPING: return THEME.shopping;
    case Category.FOOD: return THEME.food;
    case Category.TRANSPORT: return THEME.transport;
    case Category.UTILITIES: return THEME.utilities;
    case Category.HEALTH: return THEME.insurance;
    default: return THEME.other;
  }
};

const MoneyFlow: React.FC<MoneyFlowProps> = ({ transactions, formatCurrency, userPlan }) => {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const data = useMemo(() => {
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();

    // 1. Filter Transactions for Current Month
    const monthTxs = transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const incomeTxs = monthTxs.filter(t => t.type === TransactionType.INCOME);
    const expenseTxs = monthTxs.filter(t => t.type === TransactionType.EXPENSE);

    const totalIncome = incomeTxs.reduce((acc, t) => acc + t.amount, 0);
    const totalExpense = expenseTxs.reduce((acc, t) => acc + t.amount, 0);
    const savings = Math.max(0, totalIncome - totalExpense);
    // If expenses > income, we need a "Deficit" source or just show what we have
    const deficit = Math.max(0, totalExpense - totalIncome);

    // --- Nodes Construction ---
    const nodes: { name: string; value?: number; color?: string; depth?: number }[] = [];
    const links: { source: number; target: number; value: number }[] = [];

    // --- Layer 1: Income Sources ---
    const incomeMap: Record<string, number> = {};
    incomeTxs.forEach(t => {
        const key = t.merchant || 'Other Income';
        incomeMap[key] = (incomeMap[key] || 0) + t.amount;
    });

    // If no income, mock a "Starting Balance" for visualization if there are expenses
    if (totalIncome === 0 && totalExpense > 0) {
        incomeMap['Existing Funds'] = totalExpense;
    }

    const sortedIncome = Object.entries(incomeMap).sort((a,b) => b[1] - a[1]);

    // Add Layer 1 Nodes
    sortedIncome.forEach(([name, val]) => {
        nodes.push({ name, value: val, color: THEME.income });
    });
    if (deficit > 0 && totalIncome > 0) {
        nodes.push({ name: 'Deficit / Credit', value: deficit, color: THEME.debt });
    }

    // --- Layer 2: The Budget (Central Hub) ---
    const budgetIndex = nodes.length;
    const totalFlow = Math.max(totalIncome + deficit, totalExpense); // Ensure balance
    nodes.push({ name: 'Total Budget', value: totalFlow, color: THEME.budget });

    // --- Layer 3: Expenses & Savings ---
    const expenseMap: Record<string, number> = {};
    expenseTxs.forEach(t => {
        expenseMap[t.category] = (expenseMap[t.category] || 0) + t.amount;
    });

    const sortedExpenses = Object.entries(expenseMap).sort((a,b) => b[1] - a[1]);

    // Add Layer 3 Nodes
    const expenseStartIndex = nodes.length;
    sortedExpenses.forEach(([cat, val]) => {
        nodes.push({ name: cat, value: val, color: getCategoryColor(cat) });
    });

    if (savings > 0) {
        nodes.push({ name: 'Savings', value: savings, color: THEME.savings });
    }

    // --- Build Links ---

    // Link Layer 1 -> Layer 2
    let currentIdx = 0;
    sortedIncome.forEach(([_, val]) => {
        links.push({ source: currentIdx, target: budgetIndex, value: val });
        currentIdx++;
    });
    if (deficit > 0 && totalIncome > 0) {
        links.push({ source: currentIdx, target: budgetIndex, value: deficit });
        currentIdx++; // increment for next loop if needed
    } else if (totalIncome === 0 && totalExpense > 0) {
         // Existing funds case
         links.push({ source: 0, target: budgetIndex, value: totalExpense });
    }

    // Link Layer 2 -> Layer 3
    let targetIdx = expenseStartIndex;
    sortedExpenses.forEach(([_, val]) => {
        links.push({ source: budgetIndex, target: targetIdx, value: val });
        targetIdx++;
    });
    if (savings > 0) {
        links.push({ source: budgetIndex, target: targetIdx, value: savings });
    }

    return { nodes, links, totalFlow };
  }, [transactions]);

  if (data.nodes.length === 0 || data.totalFlow === 0) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[500px] text-center p-10 bg-slate-900/20 rounded-[3rem] border border-white/5 relative overflow-hidden group">
            <div className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px] opacity-20"></div>
            <div className="w-24 h-24 bg-slate-800 rounded-[2rem] flex items-center justify-center mb-6 shadow-2xl group-hover:scale-110 transition-transform duration-500 border border-white/5 relative z-10">
                <Wallet className="w-12 h-12 text-slate-600" />
            </div>
            <h3 className="text-2xl font-black text-white mb-2 relative z-10">Flow Inactive</h3>
            <p className="text-slate-400 max-w-md relative z-10">Log income and expenses to visualize your budget topology.</p>
        </div>
      );
  }

  // Custom Renderers based on the Image Style
  const SankeyNode = ({ x, y, width, height, index, payload }: any) => {
      if (!payload) return null;

      const isLeft = x < 200;
      const isRight = x > 600; // Approximate container width logic

      // Determine percent of total budget
      const percent = ((payload.value / data.totalFlow) * 100).toFixed(1) + '%';
      const showLabel = height > 10; // Hide labels for tiny nodes

      return (
        <g 
            onMouseEnter={() => setActiveIndex(index)}
            onMouseLeave={() => setActiveIndex(null)}
            className="cursor-pointer"
        >
            {/* The Node Bar */}
            <Rectangle
                x={x}
                y={y}
                width={width}
                height={height}
                fill={payload.color || '#888'}
                fillOpacity={0.9}
                radius={2}
                stroke={activeIndex === index ? "#fff" : "none"}
                strokeWidth={1}
            />

            {/* Label Logic */}
            {showLabel && (
                <text
                    x={isLeft ? x - 6 : x + width + 6}
                    y={y + height / 2}
                    textAnchor={isLeft ? 'end' : 'start'}
                    alignmentBaseline="middle"
                    fill="#fff"
                    fontSize={11}
                    fontWeight="bold"
                    style={{ pointerEvents: 'none', textShadow: '0 1px 3px rgba(0,0,0,0.8)' }}
                >
                    {payload.name}
                </text>
            )}
            {/* Value Logic */}
            {showLabel && (
                <text
                    x={isLeft ? x - 6 : x + width + 6}
                    y={y + height / 2 + 12}
                    textAnchor={isLeft ? 'end' : 'start'}
                    alignmentBaseline="middle"
                    fill={payload.color}
                    fontSize={10}
                    fontWeight="bold"
                    fontFamily="monospace"
                    style={{ pointerEvents: 'none', textShadow: '0 1px 2px rgba(0,0,0,0.8)' }}
                >
                    {formatCurrency(payload.value)} ({percent})
                </text>
            )}
        </g>
      );
  };

  const SankeyLink = (props: any) => {
      const { sourceX, targetX, sourceY, targetY, sourceControlX, targetControlX, linkWidth, index, source, target } = props;

      // Safety check
      if (!source || !target) return null;

      const isHovered = activeIndex === source.index || activeIndex === target.index;
      const opacity = isHovered ? 0.8 : 0.35;

      return (
        <path
          d={`
            M${sourceX},${sourceY}
            C${sourceControlX},${sourceY} ${targetControlX},${targetY} ${targetX},${targetY}
            L${targetX},${targetY + linkWidth}
            C${targetControlX},${targetY + linkWidth} ${sourceControlX},${sourceY + linkWidth} ${sourceX},${sourceY + linkWidth}
            Z
          `}
          fill={source.color} // Use source color for the flow
          stroke="none"
          fillOpacity={opacity}
          style={{ transition: 'fill-opacity 0.3s ease' }}
        />
      );
  };

  return (
    <div className="animate-slide-up pb-20 space-y-8">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3 uppercase">
               Capital Flow
            </h2>
            <span className="px-3 py-1 rounded-full bg-slate-800 text-slate-400 text-[10px] font-black tracking-widest border border-white/5">MONTHLY VIEW</span>
          </div>
          <p className="text-slate-400 font-medium">Visualizing the journey of every dollar from source to destination.</p>
        </div>
      </div>

      <div className="glass-card p-4 md:p-8 rounded-[2rem] border border-white/10 bg-[#020617] relative overflow-hidden min-h-[600px] flex flex-col shadow-2xl">
          {/* Subtle Grid Background */}
          <div className="absolute inset-0 bg-[linear-gradient(to_right,#1e293b_1px,transparent_1px),linear-gradient(to_bottom,#1e293b_1px,transparent_1px)] bg-[size:40px_40px] opacity-10 pointer-events-none"></div>

          <div className="flex-1 w-full relative z-10 h-[500px]">
              <ResponsiveContainer width="100%" height="100%">
                  <Sankey
                    data={data}
                    nodeWidth={16} // Thinner nodes like image 2
                    nodePadding={20}
                    margin={{ left: 120, right: 160, top: 20, bottom: 20 }}
                    link={SankeyLink}
                    node={SankeyNode}
                  >
                    <Tooltip 
                        content={({ active, payload }) => {
                            if (!active || !payload || !payload.length) return null;
                            const d = payload[0].payload;
                            const isLink = d.source && d.target;

                            if (isLink) {
                                return (
                                    <div className="bg-slate-950/90 border border-white/10 p-3 rounded-xl shadow-xl backdrop-blur-md text-xs">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="font-bold text-slate-300">{d.source.name}</span>
                                            <ArrowRight className="w-3 h-3 text-slate-500" />
                                            <span className="font-bold text-white">{d.target.name}</span>
                                        </div>
                                        <div className="text-lg font-black text-white">{formatCurrency(d.value)}</div>
                                    </div>
                                );
                            }
                            return null; // Node tooltip handled by SVG text
                        }}
                    />
                  </Sankey>
              </ResponsiveContainer>
          </div>

          <div className="flex justify-center items-center gap-6 mt-4 opacity-60">
              <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{background: THEME.income}}></div><span className="text-[10px] uppercase font-bold text-slate-400">Income</span></div>
              <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{background: THEME.budget}}></div><span className="text-[10px] uppercase font-bold text-slate-400">Budget</span></div>
              <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{background: THEME.housing}}></div><span className="text-[10px] uppercase font-bold text-slate-400">Expenses</span></div>
              <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{background: THEME.savings}}></div><span className="text-[10px] uppercase font-bold text-slate-400">Savings</span></div>
          </div>
      </div>
    </div>
  );
};

