import React, { useMemo } from "react";
import { Sankey, Tooltip, ResponsiveContainer } from "recharts";
import { Transaction, TransactionType } from "../types";

interface SankeyChartProps {
  transactions: Transaction[];
  formatCurrency: (amount: number) => string | React.ReactNode;
}

const SankeyChart: React.FC<SankeyChartProps> = ({ transactions, formatCurrency }) => {
  const data = useMemo(() => {
    // 1. Calculate Inflows
    const incomeTxs = transactions.filter(t => t.type === TransactionType.INCOME);
    const totalIncome = incomeTxs.reduce((sum, t) => sum + t.amount, 0);

    // 2. Calculate Outflows by Category
    const expenseTxs = transactions.filter(t => t.type === TransactionType.EXPENSE);
    const expenseMap: Record<string, number> = {};
    let totalExpense = 0;

    expenseTxs.forEach(t => {
        expenseMap[t.category] = (expenseMap[t.category] || 0) + t.amount;
        totalExpense += t.amount;
    });

    // 3. Construct Nodes & Links
    // Structure: Sources (0,1) -> Budget (2) -> Destinations (3...)

    const nodes: { name: string }[] = [
        { name: "Wages / Income" }, // 0
        { name: "Reserves" },       // 1 (Deficit funding)
        { name: "Total Budget" },   // 2 (Center Hub)
    ];

    const links: { source: number; target: number; value: number }[] = [];

    // Link: Income -> Budget
    if (totalIncome > 0) {
        links.push({ source: 0, target: 2, value: totalIncome });
    }

    // Link: Reserves -> Budget (if spending > income, or if income is 0)
    const deficit = Math.max(0, totalExpense - totalIncome);
    if (deficit > 0) {
        links.push({ source: 1, target: 2, value: deficit });
    } else if (totalIncome === 0 && totalExpense > 0) {
        links.push({ source: 1, target: 2, value: totalExpense });
    }

    // Link: Budget -> Expenses & Savings
    const savings = Math.max(0, totalIncome - totalExpense);

    // Sort expenses for cleaner layout
    const sortedExpenses = Object.entries(expenseMap).sort((a,b) => b[1] - a[1]);

    sortedExpenses.forEach(([category, amount]) => {
        if (amount > 0) {
            nodes.push({ name: category });
            links.push({ source: 2, target: nodes.length - 1, value: amount });
        }
    });

    // Link: Budget -> Savings
    if (savings > 0) {
        nodes.push({ name: "Savings" });
        links.push({ source: 2, target: nodes.length - 1, value: savings });
    }

    return { nodes, links };
  }, [transactions]);

  if (data.nodes.length < 2 || data.links.length === 0) {
      return (
          <div className="w-full h-[500px] flex items-center justify-center bg-slate-900/40 rounded-[2rem] border border-white/5">
              <p className="text-slate-500 font-bold">Insufficient data for Sankey Diagram</p>
          </div>
      );
  }

  return (
    <div className="w-full h-[700px] bg-slate-900/40 shadow-2xl rounded-[2rem] p-6 border border-white/5 flex flex-col animate-slide-up">
      <div className="mb-6">
          <h2 className="text-xl font-bold text-white mb-1">Income Distribution Sankey</h2>
          <p className="text-xs text-slate-400 font-medium">Flow visualization of capital from source to category.</p>
      </div>
      <div className="flex-1 min-h-0">
        <ResponsiveContainer width="100%" height="100%">
            <Sankey
                data={data}
                nodePadding={50}
                nodeWidth={16}
                link={{ stroke: "#6366f1", strokeOpacity: 0.3 }}
                node={{ stroke: 'none', fill: '#818cf8' }}
                margin={{ left: 20, right: 20, top: 20, bottom: 20 }}
            >
                <Tooltip 
                    contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', borderRadius: '12px', color: '#f8fafc', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.5)' }}
                    itemStyle={{ color: '#f8fafc', fontWeight: 'bold' }}
                    formatter={(value: number, name: string) => [formatCurrency(value), name]}
                />
            </Sankey>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default SankeyChart;

