                                Advanced capital flow topology requires a Pro or Elite uplink. Visualize your financial biology with high-fidelity pathing.
                            </p>
                            <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-slate-950 font-black rounded-2xl hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center justify-center gap-2 uppercase text-xs tracking-widest group">
                                <Zap className="w-4 h-4 fill-indigo-600 text-indigo-600 group-hover:scale-110 transition-transform" /> Upgrade Terminal
                            </button>
                        </div>
                    </div>
                ) : (
                    <SankeyChart transactions={transactions} formatCurrency={formatCurrency} />
                )
            )}
            {activeTab === 'sandbox' && (
                <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={onUpgradeClick} insightUsage={insightUsage} onIncrementUsage={onIncrementUsage} />
            )}
            {activeTab === 'negotiator' && (
                <BillNegotiator userPlan={userPlan} onIncrementUsage={onIncrementNegotiationUsage} negotiationUsage={negotiationUsage} transactions={transactions} />
            )}
        </div>
    </div>
  );
};

export default SmartMoney;

